local UIActivityRoleSendLettersPanel = Class('UIActivityRoleSendLettersPanel')

function UIActivityRoleSendLettersPanel:__init()
    self._data = nil
    self._vo = nil
    self._allWordIds = {}
end

function UIActivityRoleSendLettersPanel:__delete()
    self._data = nil
    self._vo = nil
    self._allWordIds = {}
end

function UIActivityRoleSendLettersPanel:Awake()
    SetButtonAction(self.BtnReceive, Bind(self, self.OnBtnReceive))
    SetButtonAction(self.BtnChest, Bind(self, self.OnBtnChest))
    SetButtonAction(self.TextPlayExplain, Bind(self, self.OnBtnTips))
    SetButtonAction(self.BtnGo, Bind(self, self.OnBtnJump))
end

function UIActivityRoleSendLettersPanel:Refresh(data, parLua)
    if not data then
        return
    end
    self._isJump = false
    self._data = data
    self._parLua = parLua

    GameUtils.Request(Interfaces.ActivitySendLetterHome, {activityUuid = self._data.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
    
        local jsonData = response.data


        local vo = CfUtils.GetCfVo(AutoIds.IdSetting2830, "SendWordPlanVo", jsonData.activityConf.id)
        self._vo = vo
        if not self._vo then
            return
        end
        SendWordComponent:Initial(jsonData, self._data.id)

        local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2831, jsonData.activityConf.id)
        self._allWordIds = checkTable(t)

        self:FillSelf()

        CfUtils.RefreshTopGoods({self._vo.itemId})

        self:RefreshRedPoint()

        CfUtils.SetActive(self.RewardGroup, true)
        CfUtils.SetActive(self.BtnGo, true)
    end)
end

function UIActivityRoleSendLettersPanel:FillSelf()
    local startTime = self._data.startTime
    local closeTime = self._data.closeTime
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    CfUtils.FillText(self.TxtContent, self._data.detail)
    CfUtils.FillWebRawImage(self.ImgTitleName, self._data.titleImage)
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self._vo.itemId))

    self:FillReward()
    self:FillWords()

    CfUtils.SetActive(self.w, checkNumber(self._vo.itemId) > 0)
end

function UIActivityRoleSendLettersPanel:FillReward()
    local rewards = CfUtils.Split(self._vo.reward) 
    local nums = CfUtils.Split(self._vo.rewardNum) 

    local num1 = table.count(self._allWordIds)
    local num2 = SendWordComponent:GetUnlockRewardNum()
    CfUtils.FillText(self.TxtNumber, localize("<color=#00fff2>_num1_</color>/_num2_", {_num1_ = num2, _num2_ = num1}))
    self.ImgProgreassLine.fillAmount = num2/num1

    local isCanDraw = SendWordComponent:IsCanDrawBox()
    local isDraw = SendWordComponent:IsDrawBox()

    if isDraw then
        CfUtils.PlayAnimation(self.BtnChest.transform:Find("AnimRoot"), "SendLetter_Box_hasGet")
    else
        if isCanDraw then
            CfUtils.PlayAnimation(self.BtnChest.transform:Find("AnimRoot"), "SendLetter_Box_canGet")
        else
            CfUtils.PlayAnimation(self.BtnChest.transform:Find("AnimRoot"), "SendLetter_Box_Normal")
        end
    end

    local status1 = 1
    local status2 = 1

    if isDraw then
        status1 = 2
        status2 = 3
    else
        if isCanDraw then
            status1 = 1
            status2 = 1
        else
            status1 = 2
            status2 = 2
        end
    end
    CfUtils.SetUISwitchImage(self.BtnReceive.transform:Find("ImgBg"), status1)
    CfUtils.SetUISwitchText(self.BtnReceive.transform:Find("TxtBtn"), status2)
end

--宝箱
function UIActivityRoleSendLettersPanel:OnBtnReceive()
    local isDraw = SendWordComponent:IsDrawBox()
    local isCanDraw = SendWordComponent:IsCanDrawBox()
    if not isCanDraw then
        GameUtils.Toast(localize("获得全部信函可领取奖励"))
        return
    end
    if isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end

    SendWordComponent:ActivitySendRewardReceiveReq(function()
        self:FillReward()

        self:RefreshRedPoint()
    end)
end

function UIActivityRoleSendLettersPanel:FillWords()
    if self._isInit then
        GameUtils.ReloadData(self.ScrollViewCardList, table.count(self._allWordIds), true)
    else
        self._isInit = true
        self.ScrollViewCardList:InitGridView(table.count(self._allWordIds), Bind(self, self.OnRefreshPartsIndex))
    end
end

function UIActivityRoleSendLettersPanel:OnRefreshPartsIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("ItemCell")
    local data = self._allWordIds[index + 1]

    local scr = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.ActivityMainDialog.UIActivityRoleSendLettersPanelNode")
    if scr then
        scr:Refresh(data, function()
            self:FillReward()

            self:RefreshRedPoint()
        end)
    end

    return cell
end

function UIActivityRoleSendLettersPanel:OnBtnChest()
    local rewards = CfUtils.Split(self._vo.reward) 
    local nums = CfUtils.Split(self._vo.rewardNum) 

    local t = {}

    for k, v in pairs(rewards) do
        local reward = {
            ["id"] = rewards[k],
            ["goodsId"] = rewards[k],
            ["num"] = checkNumber(nums[k])
        }
        table.insert(t, reward)
    end
    GameUtils.ShowCommonTipsBoardRewardPreview(self.BtnChest.gameObject, t, localize('奖励预览:'), false, true)
end

--提示
function UIActivityRoleSendLettersPanel:OnBtnTips()
    if checkNumber(self._vo.ruleID) > 0 then
        CfUtils.ShowModuleToast(self._vo.ruleID)
    end
end

--
function UIActivityRoleSendLettersPanel:OnBtnJump()
    local t = ActivityMgr:GetInstance():GetActivityData()
    if not t then
        return
    end
    if self._isJump then
        return
    end
    self._isJump = true
    local ind = 0
    local data = nil
    for k, v in pairs(t) do
        if checkInt(v.type) == ActivityConstants.ActivityType.BossChallenge then
            data = v
            ind = k
            break
        end
    end

    self._parLua:RefreshNode(data.id)
    self._parLua:RefreshToggleById(data.id)
end

function UIActivityRoleSendLettersPanel:RefreshRedPoint()
    local num = 1
    local isDraw = SendWordComponent:IsDrawBox()
    local isCanDraw = SendWordComponent:IsCanDrawBox()
    if not isDraw and isCanDraw then
        GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivitySendWord , 1)
        ActivityUtils.UpdateActivityMainRedPointState(self._data.id, 0)
        return
    end
    
    for k, v in pairs(self._allWordIds) do
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting2831, "SendWordWordVo", v)
        local isUnlock = SendWordComponent:IsUnlockReward(vo.id)
        if not isUnlock then
            if GoodsUtils.GetThingNo(vo.unlockItem) >= checkNumber(vo.unlockNum) then 
                GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivitySendWord , 1)
                ActivityUtils.UpdateActivityMainRedPointState(self._data.id, 0)
                return
            end
        end
    end
    ActivityUtils.UpdateActivityMainRedPointState(self._data.id, -1)
    GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivitySendWord , 0)
end

function UIActivityRoleSendLettersPanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityRoleSendLettersPanel
